
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_c_revscan_vv10_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_c_revscan_vv10", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-2.811397806474749e-02, -2.806341776620626e-02, -2.798829672944800e-02, -2.787506682827719e-02, -2.770080981987785e-02, -2.742452502469669e-02, -2.696807742356388e-02, -2.617698110990694e-02, -2.480728492805282e-02, -2.348195693969353e-02, -2.418078732526356e-02, -4.602779494949893e-02, -4.261324718747363e-02, -2.564545298271334e-02, -1.857203692642202e-02, -1.216128566968773e-02, -5.986086290105205e-03, -2.672202022450063e-03, -5.453819309567616e-04, -3.190339195713528e-05]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


